package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6"
	"github.com/spf13/cobra"
)

type whyOptions struct {
	Path        string
	LineRange   string
	Interactive bool
	NoPager     bool
}

type whyLineRange struct {
	Start int
	End   int
}

func newWhyCmd() *cobra.Command {
	var opts whyOptions

	cmd := &cobra.Command{
		Use:    "why [path]",
		Short:  "Explain why a file looks the way it does",
		Hidden: true,
		Args:   cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				opts.Path = args[0]
			}
			return runWhy(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), opts)
		},
	}

	cmd.Flags().StringVarP(&opts.LineRange, "lines", "L", "", "Show a specific line or line range")
	cmd.Flags().BoolVarP(&opts.Interactive, "interactive", "i", false, "Force interactive TUI mode")
	cmd.Flags().BoolVar(&opts.NoPager, "no-pager", false, "Disable pager output")

	return cmd
}

func runWhy(ctx context.Context, w io.Writer, _ io.Writer, opts whyOptions) error {
	canUseTUI := canRunWhyTUI(w)
	if opts.Interactive && !canUseTUI {
		return errors.New("interactive mode requires a real terminal")
	}
	if opts.Path == "" {
		if !canUseTUI {
			return errors.New("path required when not running interactively")
		}
		return errors.New("interactive file browser is not implemented yet")
	}
	if _, err := parseWhyLineRange(opts.LineRange); err != nil {
		return err
	}
	repoRoot, gitPath, _, err := resolveWhyPath(ctx, opts.Path)
	if err != nil {
		return err
	}
	if err := whyPathExistsAtHEAD(ctx, repoRoot, gitPath); err != nil {
		return err
	}
	return errors.New("entire why is not implemented yet")
}

func canRunWhyTUI(w io.Writer) bool {
	return !IsAccessibleMode() && interactive.IsTerminalWriter(w) && interactive.CanPromptInteractively()
}

func parseWhyLineRange(raw string) (whyLineRange, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return whyLineRange{}, nil
	}

	parseLine := func(value string) (int, error) {
		n, err := strconv.Atoi(value)
		if err != nil || n <= 0 {
			return 0, fmt.Errorf("invalid line range %q", raw)
		}
		return n, nil
	}

	if strings.Contains(raw, "-") {
		parts := strings.Split(raw, "-")
		if len(parts) != 2 {
			return whyLineRange{}, fmt.Errorf("invalid line range %q", raw)
		}
		start, err := parseLine(parts[0])
		if err != nil {
			return whyLineRange{}, err
		}
		end, err := parseLine(parts[1])
		if err != nil {
			return whyLineRange{}, err
		}
		if start > end {
			return whyLineRange{}, fmt.Errorf("invalid line range %q: start must be <= end", raw)
		}
		return whyLineRange{Start: start, End: end}, nil
	}

	line, err := parseLine(raw)
	if err != nil {
		return whyLineRange{}, err
	}
	return whyLineRange{Start: line, End: line}, nil
}

func (r whyLineRange) gitRange() string {
	if r.Start == 0 && r.End == 0 {
		return ""
	}
	return fmt.Sprintf("%d,%d", r.Start, r.End)
}

func resolveWhyPath(ctx context.Context, input string) (string, string, string, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", "", "", fmt.Errorf("not a git repository: %w", err)
	}
	repoRoot = normalizeWhyPathForRel(repoRoot)

	absPath := input
	if !filepath.IsAbs(absPath) {
		absPath, err = filepath.Abs(absPath)
		if err != nil {
			return "", "", "", fmt.Errorf("resolving path %q: %w", input, err)
		}
	}
	absPath = normalizeWhyPathForRel(absPath)

	relPath, err := filepath.Rel(repoRoot, absPath)
	if err != nil {
		return "", "", "", fmt.Errorf("resolving path %q relative to repository: %w", input, err)
	}
	if relPath == "." || strings.HasPrefix(relPath, ".."+string(filepath.Separator)) || relPath == ".." {
		return "", "", "", fmt.Errorf("path %q is outside the repository", input)
	}

	return repoRoot, filepath.ToSlash(relPath), absPath, nil
}

func normalizeWhyPathForRel(path string) string {
	cleaned := filepath.Clean(path)
	if resolved, err := filepath.EvalSymlinks(cleaned); err == nil {
		return resolved
	}
	dir := filepath.Dir(cleaned)
	base := filepath.Base(cleaned)
	if resolvedDir, err := filepath.EvalSymlinks(dir); err == nil {
		return filepath.Join(resolvedDir, base)
	}
	return cleaned
}

func whyPathExistsAtHEAD(_ context.Context, repoRoot, gitPath string) error {
	repo, err := git.PlainOpen(repoRoot)
	if err != nil {
		return fmt.Errorf("opening repository: %w", err)
	}
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("resolving HEAD: %w", err)
	}
	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return fmt.Errorf("reading HEAD commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return fmt.Errorf("reading HEAD tree: %w", err)
	}
	if _, err := tree.File(gitPath); err != nil {
		return fmt.Errorf("path %q does not exist as a file at HEAD: %w", gitPath, err)
	}
	return nil
}

